const now = new Date().toISOString();
const ins = db.prepare(`INSERT INTO jobs (id,status,input,steps,fail_attempts,attempts,completed,created_at,updated_at,available_at) VALUES (?,?,?,?,?,?,?,?,?,0)`);
ins.run("crash-3-fail3","running","hello",3,3,3,0,now,now);
ins.run("crash-1-fail3","running","one",2,3,1,0,now,now);
ins.run("crash-2-fail3","running","hi",2,3,2,0,now,now);
ins.run("crash-run-fail1","running","go",2,1,2,0,now,now);
ins.run("crash-run-fail0-mid","running","mid",20,0,1,7,now,now);
db.close();'
export PORT=$(node -e 'const s=require("net").createServer().listen(0,"127.0.0.1",()=>{console.log(s.address().port);s.close()})')
node --disable-warning=ExperimentalWarning dist/worker.js > $D/worker.log 2>&1 & W=$!
node --disable-warning=ExperimentalWarning dist/server.js > $D/server.log 2>&1 & S=$!
sleep 5
curl -s http://127.0.0.1:$PORT/api/jobs | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{for(const j of JSON.parse(s).jobs)console.log(j.input,j.status,"attempts="+j.attempts,JSON.stringify(j.result),j.error)})'
kill -TERM $W $S; sleep 1; wait 2>/dev/null; cat $D/worker.log
